commands.command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$task = Get-Content -LiteralPath .'"\\task.json -Raw | ConvertFrom-Json
"'$medians = foreach ($name in @('"'baseline', 'candidate')) {
    "'$means = @($task.$name.latencies_ms | ForEach-Object { ($_ | Measure-Object -Average).Average })
    $sorted = @($means | Sort-Object)
    [pscustomobject]@{ name = $name; trial_means_ms = $means; median_ms = $sorted[2] }
}
$rawReduction = 100 * (1 - $medians[1].median_ms / $medians[0].median_ms)
[pscustomobject]@{ datasets = $medians; apparent_reduction_pct = $rawReduction } | ConvertTo-Json -Depth 5'
